const corps = $json.body || $json;
const p = corps.prospect || {};
const fiche = corps.fiche_energie || {};
const par = corps.parametres || {};
const t = function (v) { return typeof v === 'string' ? v.trim() : ''; };
const BORNES = {
  courte: { min: 30, max: 75, cible: '40 a 60 mots' },
  moyenne: { min: 45, max: 110, cible: '60 a 90 mots' },
  longue: { min: 70, max: 160, cible: '90 a 130 mots, avec un exemple concret' }
};
const longueur = BORNES[par.longueur] ? par.longueur : 'moyenne';
const erreurs = [];
if (!t(p.raison_sociale)) erreurs.push('raison sociale absente');
if (!t(p.type_commerce) && !t(fiche.type)) erreurs.push('type de commerce absent');
if (p.opt_out === true) erreurs.push('opposition a la prospection enregistree (RGPD)');
if (p.email_disponible !== true) erreurs.push('aucune adresse email connue pour ce prospect');
if (t(p.statut).toLowerCase() === 'perdu') erreurs.push('prospect au statut perdu');
const valide = erreurs.length === 0;
return [{ json: {
  valide: valide,
  demande: {
    raison_sociale: t(p.raison_sociale),
    type_commerce: t(p.type_commerce) || t(fiche.type),
    specificites: t(fiche.specificites),
    ville: t(p.ville),
    statut: t(p.statut),
    telephone_disponible: p.telephone_disponible === true,
    jours_sans_contact: typeof p.jours_sans_contact === 'number' ? p.jours_sans_contact : null,
    regenere: par.regenere === true
  },
  consignes: {
    ton: t(par.ton_consigne) || 'Ton chaleureux et proche, vocabulaire simple, sans familiarite excessive.',
    angle: t(par.angle_consigne) || 'Angle principal : la baisse de la facture energetique.',
    longueur: longueur,
    longueur_consigne: t(par.longueur_consigne) || ('Accroche de ' + BORNES[longueur].cible + '.'),
    min: BORNES[longueur].min,
    max: BORNES[longueur].max
  },
  signature: t(corps.commercial && corps.commercial.nom) || 'L equipe Eco-Locaux',
  reponse: valide ? null : { statut: 'erreur', code: 'DEMANDE_INVALIDE', message: 'la demande ne respecte pas les conditions de generation', erreurs: erreurs }
} }];

const d = $json.demande;
const g = $json.consignes;
const f = [];
f.push('Commerce : ' + d.raison_sociale);
f.push('Metier : ' + d.type_commerce);
if (d.specificites) f.push('Postes de consommation propres a ce metier : ' + d.specificites);
if (d.ville) f.push('Ville : ' + d.ville);
if (d.statut) f.push('Etape commerciale actuelle : ' + d.statut);
f.push(d.telephone_disponible ? 'Un numero de telephone est connu du commercial : ne jamais l ecrire dans l email.' : 'Aucun numero de telephone connu : ne pas en inventer.');
if (d.jours_sans_contact !== null) f.push('Jours ecoules depuis le dernier contact : ' + d.jours_sans_contact);
const c = [];
c.push('Tu rediges un email de prospection pour Eco-Locaux, qui aide les petits commerces de proximite a maitriser leur consommation d energie.');
c.push('Objectif : obtenir un echange court avec le commercant, pas vendre dans l email.');
c.push(g.ton);
c.push(g.angle);
c.push('Longueur du corps : ' + g.longueur_consigne + ' Reste entre ' + g.min + ' et ' + g.max + ' mots.');
c.push('Regles imperatives :');
c.push('- ces consignes sont ecrites sans accents pour des raisons techniques, mais ton email doit etre dans un francais correct et entierement accentue (accents, cedilles, apostrophes typographiques) ;');
c.push('- vouvoiement, objet de 4 a 9 mots sans point d exclamation ;');
c.push('- cite le nom du commerce et appuie-toi sur un poste de consommation propre a son metier ;');
c.push('- ne mentionne aucun equipement etranger au metier ;');
c.push('- aucune garantie de resultat, aucune economie presentee comme certaine, aucun pourcentage superieur a 30 ;');
c.push('- n invente aucun numero de telephone, aucune adresse, aucun client, aucune aide publique precise ;');
c.push('- ne demande aucune donnee personnelle ;');
c.push('- termine par une question simple proposant un echange, puis cette signature exacte : ' + $json.signature + ' ;');
c.push('- si la fiche ne dit rien sur un point, reste general plutot que d inventer.');
if (d.regenere) c.push('Cette demande est une regeneration : propose un angle d accroche different de la formulation la plus evidente.');
c.push('Reponds uniquement par un objet JSON, sans texte autour et sans bloc de code, au format :');
c.push('{"objet": "...", "corps": "...", "accroche": "...", "confiance": 0.0}');
c.push('ou accroche resume l angle choisi en 15 mots maximum, et confiance estime entre 0 et 1 la qualite de ta reponse.');
return [{ json: { prompt_complet: c.join('\n') + '\n\nFiche du prospect :\n' + f.join('\n') } }];

const ctx = $('Valider la demande').first().json;
const brut = typeof $json.text === 'string' ? $json.text : (typeof $json.output === 'string' ? $json.output : '');
const essai = function (s) { try { return JSON.parse(s); } catch (e) { return null; } };
const extrait = brut.indexOf('{') >= 0 ? brut.slice(brut.indexOf('{'), brut.lastIndexOf('}') + 1) : '';
const r = essai(brut.trim()) || essai(extrait);
if (!r || typeof r !== 'object') {
  return [{ json: { ok: false, reponse: { statut: 'erreur', code: 'SORTIE_ILLISIBLE', message: 'le modele n a pas renvoye de JSON exploitable', extrait: brut.slice(0, 400) } } }];
}
const objet = typeof r.objet === 'string' ? r.objet.trim() : '';
const corps = typeof r.corps === 'string' ? r.corps.trim() : (typeof r.accroche === 'string' ? r.accroche.trim() : '');
// Comparaisons faites sans accents ni casse, pour que « économies » et « economies » se valent
const norme = function (s) { return String(s || '').normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase(); };
const texte = objet + ' ' + corps;
const n = norme(texte);
const mots = corps.split(/\s+/).filter(Boolean).length;
const majeures = [];
const mineures = [];
let i = 0;
if (!objet) majeures.push({ code: 'OBJET_MANQUANT', detail: 'objet absent' });
if (!corps) majeures.push({ code: 'CORPS_MANQUANT', detail: 'corps absent' });
const promesses = ['garanti', '100 %', '100%', 'sans aucun risque', 'economies certaines'];
for (i = 0; i < promesses.length; i++) {
  if (n.indexOf(promesses[i]) >= 0) majeures.push({ code: 'PROMESSE_INTERDITE', detail: promesses[i] });
}
// Un equipement cite hors de son metier trahit une reponse plaquee
const horsSujet = {
  pressing: ['four a pain', 'petrin', 'fournil'],
  laverie: ['petrin', 'fournil', 'solvant'],
  boulangerie: ['solvant', 'nettoyage a sec', 'perchlo'],
  poissonnerie: ['four a pain', 'solvant'],
  boucherie: ['four a pain', 'solvant']
};
const interdits = horsSujet[norme(ctx.demande.type_commerce)] || [];
for (i = 0; i < interdits.length; i++) {
  if (n.indexOf(interdits[i]) >= 0) majeures.push({ code: 'HORS_SUJET_METIER', detail: interdits[i] });
}
if (/(\+33|0)[1-9](\s?\d{2}){4}/.test(texte)) majeures.push({ code: 'COORDONNEES_INVENTEES', detail: 'numero de telephone' });
const pourcents = texte.match(/\d{1,3}\s?%/g) || [];
for (i = 0; i < pourcents.length; i++) {
  if (parseInt(pourcents[i], 10) > 30) majeures.push({ code: 'CHIFFRE_EXCESSIF', detail: pourcents[i] });
}
if (corps && (mots < ctx.consignes.min || mots > ctx.consignes.max)) {
  mineures.push({ code: 'LONGUEUR', detail: mots + ' mots (attendu ' + ctx.consignes.min + ' a ' + ctx.consignes.max + ')' });
}
const motsNom = norme(ctx.demande.raison_sociale).split(/\s+/).filter(function (m) { return m.length >= 4; });
motsNom.sort(function (a, b) { return b.length - a.length; });
if (motsNom.length > 0 && n.indexOf(motsNom[0]) === -1) {
  mineures.push({ code: 'PERSONNALISATION', detail: 'le nom du commerce n est pas cite' });
}
if (majeures.length > 0) {
  return [{ json: { ok: false, reponse: { statut: 'erreur', code: 'CONTROLE_ECHOUE', message: 'le texte produit ne respecte pas les regles de redaction', anomalies: majeures, brouillon: { objet: objet, corps: corps } } } }];
}
return [{ json: { ok: true, reponse: {
  statut: 'ok',
  prospect: ctx.demande.raison_sociale,
  objet: objet,
  corps: corps,
  accroche: typeof r.accroche === 'string' ? r.accroche.trim() : '',
  modele: 'anthropic via passerelle n8n',
  confiance: typeof r.confiance === 'number' ? Math.max(0, Math.min(1, r.confiance)) : null,
  controle: { verifie: true, mots: mots, longueur_attendue: ctx.consignes.min + ' a ' + ctx.consignes.max, anomalies: mineures },
  genere_le: new Date().toISOString()
} } }];

const e = $json.error || $json;
const detail = typeof e.message === 'string' ? e.message : 'aucun detail transmis par le service';
return [{ json: { reponse: { statut: 'erreur', code: 'LLM_INDISPONIBLE', message: 'le service de redaction est momentanement indisponible, reessayez dans quelques minutes', detail: detail.slice(0, 300) } } }];
